INSERT INTO questions (id,domain_id,skill_id,drill_unit_id,framework_target_id,difficulty,question_type,prompt,choices,correct_answer,explanation,question_model_id,source_type,source_question_id,sort_order,status,requires_review,is_gate) VALUES ('g1a-easy-1','geometry-trigonometry','area-and-volume','g1a','g1a-target-1','easy','multiple_choice','A rectangle is 9 meters long and 4 meters wide. What is its area?','["13","26","36","72"]','36','Use A = lw: 9 × 4 = 36 square meters.','g1a-easy-model','original','G1-G1A-1',1,'active',0,0) ON CONFLICT(id) DO UPDATE SET domain_id=excluded.domain_id,skill_id=excluded.skill_id,drill_unit_id=excluded.drill_unit_id,framework_target_id=excluded.framework_target_id,difficulty=excluded.difficulty,question_type=excluded.question_type,prompt=excluded.prompt,choices=excluded.choices,correct_answer=excluded.correct_answer,explanation=excluded.explanation,question_model_id=excluded.question_model_id,source_question_id=excluded.source_question_id,sort_order=excluded.sort_order,status=excluded.status,requires_review=excluded.requires_review,is_gate=excluded.is_gate WHERE questions.source_type='placeholder';
